<?php
namespace App\Http\Controllers\Api\V1;use App\Models\Job;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;
class JobEngagementController{public function store(Request $r,Job $job):JsonResponse{abort_unless($job->status==='active'&&(!$job->expires_at||$job->expires_at->isFuture()),404);$d=$r->validate(['event'=>['required',Rule::in(['view','apply_start'])],'visitor_id'=>['required','string','max:100']]);DB::table('job_engagement_events')->insertOrIgnore(['job_id'=>$job->id,'event'=>$d['event'],'visitor_hash'=>hash('sha256',$d['visitor_id'].'|'.$r->ip()),'event_date'=>now()->toDateString(),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['message'=>'Métrica registrada.'],201);}}
